mapper.select:
SELECT e.*, m.name AS meeting_name, u.real_name AS referee_name, (SELECT COUNT(*) FROM t_registration r WHERE r.event_id = e.id AND r.status = 1 AND r.deleted = 0) AS current_participants FROM t_event e LEFT JOIN t_meeting m ON e.meeting_id = m.id LEFT JOIN ssms_auth.t_user u ON e.referee_id = u.id WHERE e.deleted = 0
AND e.meeting_id = #{meetingId}
AND e.name LIKE CONCAT('%', #{name}, '%')
AND e.category = #{category}
AND e.gender_limit = #{genderLimit}
AND e.status = #{status}
ORDER BY e.event_date ASC, e.start_time ASC

SELECT e.category, COUNT(*) AS event_count, SUM(CASE WHEN e.status = 0 THEN 1 ELSE 0 END) AS not_started, SUM(CASE WHEN e.status = 1 THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN e.status = 2 THEN 1 ELSE 0 END) AS completed FROM t_event e WHERE e.deleted = 0
AND e.meeting_id = #{meetingId}
GROUP BY e.category
